const _PFN = "";
function dec(s){return new TextDecoder("utf-8").decode(Uint8Array.from(atob(s),c=>c.charCodeAt(0)));}

// ── ABRIR EDITOR (idêntico ao antigo openProject() de index.html — só a
// verificação de permissão mudou de PROJECT_ROLES pra um parâmetro "papel",
// já que aqui não existe mais a lista global de projetos do index.html) ──
async function ospaOpenEditor(id, papel) {
  if (papel !== "admin" && papel !== "coordenador") {
    alert("Você não tem permissão de edição neste projeto.");
    return;
  }
  try{
    var proj=await api("GET","projetos",null,"id=eq."+id).then(function(r){return r[0];});
    var cfg=await api("GET","config_projeto",null,"projeto_id=eq."+id).then(function(r){return r[0]||{};});
    var cfls=await api("GET","conflitos",null,"projeto_id=eq."+id+"&order=ordem.asc,created_at.asc");
    var imgs=await api("GET","imagens",null,"projeto_id=eq."+id+"&order=conflito_id.asc,ordem.asc&select=conflito_id,ordem,dados");
    var imagesDB={};
    imgs.forEach(function(img){
      var c=cfls.find(function(x){return x.id===img.conflito_id;});
      if(!c)return;
      if(!imagesDB[c.codigo])imagesDB[c.codigo]=[];
      imagesDB[c.codigo][img.ordem]=img.dados;
    });
    Object.keys(imagesDB).forEach(function(k){imagesDB[k]=imagesDB[k].filter(Boolean);});
    var cdata=cfls.map(function(c){return {id:c.codigo,_db:c.id,alert:c.alerta,status:c.status,loc:c.local,disc:c.disciplinas||[],desc:c.descricao||"",sol:c.proposta||null,obs:c.observacao||null,pub:c.publicado!==false};});
    var html=dec(_EA)+JSON.stringify(imagesDB)+dec(_EB)+JSON.stringify(cdata)+dec(_EC);
    // Patch META
    function esc(s){return (s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/\r/g,'').replace(/'/g,"\u0027")}
    [["project",/project:\s*'[^']*'/,"project: '" + esc(proj.nome) + "'"],["address",/address:\s*'[^']*'/,"address: '" + esc(proj.endereco||"") + "'"],["client",/client:\s*'[^']*'/,"client:  '" + esc(proj.cliente||"") + "'"],["manager",/manager:\s*'[^']*'/,"manager: '" + esc(proj.responsavel||"") + "'"],["code",/code:\s*'[^']*'/,"code:    '" + proj.id + "'"],["rev",/rev:\s*'[^']*'/,"rev:     '" + esc(proj.revisao||"REV. 00") + "'"],["date",/date:\s*'[^']*'/,"date:    '" + esc(proj.data||"") + "'"]].forEach(function(p){html=html.replace(p[1],p[2]);});
        html=html.replace("notes:   /*__NOTES__*/''","notes:   /*__NOTES__*/'" + esc(proj.notas||"") + "'");
    // Patch CONFIG from Supabase config_projeto
    if(cfg.disciplinas&&cfg.disciplinas.length){
      var discStr=JSON.stringify(cfg.disciplinas);
      html=html.replace(/disciplines:\s*\[[^\]]*\]/,'disciplines: '+discStr);
    }
    if(cfg.locais&&cfg.locais.length){
      var locStr=JSON.stringify(cfg.locais);
      html=html.replace(/locations:\s*\[[^\]]*\]/,'locations: '+locStr);
    }
    // Inject publishViewer function
    var pfn=dec(_PFN);
    html=html.replace("render();\n<\/script>","render();\n"+pfn+"\n<\/script>");
;

    var blob=new Blob([html],{type:"text/html; charset=utf-8"});
    var url=URL.createObjectURL(blob);
    window.open(url,"_blank");
    setTimeout(function(){URL.revokeObjectURL(url);},15000);
  }catch(e){alert("Erro: "+e.message);console.error(e);}
}
